import { forwardRef, useRef, useEffect } from 'react'
import { IconBack, IconCalendar, IconCheck } from './Icons'

// ─── Date Input Mask Helpers ──────────────────────────────────────────────────
const cleanDigits = (val) => {
  return (val || '').replace(/\D/g, '').slice(0, 8)
}

const formatToDateMask = (digits) => {
  if (!digits) return ''
  if (digits.length <= 2) {
    return digits
  }
  if (digits.length <= 4) {
    return `${digits.slice(0, 2)}/${digits.slice(2)}`
  }
  return `${digits.slice(0, 2)}/${digits.slice(2, 4)}/${digits.slice(4, 8)}`
}

const parseMaskToDate = (formatted) => {
  if (!formatted) return ''
  const parts = formatted.split('/')
  if (parts.length === 3) {
    const day = parts[0]
    const month = parts[1]
    const year = parts[2]
    if (day.length === 2 && month.length === 2 && year.length === 4) {
      const d = parseInt(day, 10)
      const m = parseInt(month, 10)
      const y = parseInt(year, 10)
      if (m >= 1 && m <= 12 && d >= 1 && d <= 31 && y >= 1900 && y <= 2100) {
        const daysInMonth = new Date(y, m, 0).getDate()
        if (d <= daysInMonth) {
          return `${year}-${month}-${day}`
        }
      }
    }
  }
  return ''
}

const formatDateToMask = (isoDate) => {
  if (!isoDate) return ''
  const parts = isoDate.split('-')
  if (parts.length === 3) {
    const year = parts[0]
    const month = parts[1]
    const day = parts[2]
    if (day.length === 2 && month.length === 2 && year.length === 4) {
      return `${day}/${month}/${year}`
    }
  }
  return ''
}

const getCursorPosition = (formatted, digitsBefore) => {
  let digitCount = 0
  for (let i = 0; i < formatted.length; i++) {
    if (digitCount === digitsBefore) {
      return i
    }
    if (/\d/.test(formatted[i])) {
      digitCount++
    }
  }
  return formatted.length
}

