export function Stepper({ current }) {
  const steps = ['Tipo', 'Datos', 'Resultado']
  return (
    <div className="flex items-center justify-center sm:justify-between px-6 py-5">
      {steps.map((s, i) => (
        <div key={s} className="flex items-center">
          <div className="flex flex-col items-center gap-1">
            <div
              className={`w-8 h-8 rounded-ds-pill flex items-center justify-center text-[13px] leading-[19px] font-medium transition-all duration-300 ${
                i + 1 <= current
                  ? 'bg-orange-brand text-white'
                  : 'bg-white text-grey-500 border-hair border-blue-200'
              }`}
            >
              {i + 1 < current ? (
                <span className="w-4 h-4 flex items-center justify-center">
                  <IconCheck width="14" height="14" className="w-full h-full" />
                </span>
              ) : (
                i + 1
              )}
            </div>
            <span
              className={`text-[11px] leading-[16px] font-medium ${
                i + 1 === current ? 'text-orange-brand' : 'text-grey-500'
              }`}
            >
              {s}
            </span>
          </div>
          {i < steps.length - 1 && (
            <div
              className={`h-px w-12 sm:w-24 mx-1 mb-4 transition-all duration-300 ${
                i + 1 < current ? 'bg-orange-brand' : 'bg-blue-200'
              }`}
              style={{ height: i + 1 < current ? '1.5px' : '0.5px' }}
            />
          )}
        </div>
      ))}
    </div>
  )
}

/**
 * DateInput — styled date input with dynamic mask and real-time formatting.
 * Accepts all standard input props plus `error` boolean.
 */
export const DateInput = forwardRef(({ error, className = '', onChange, value, ...props }, ref) => {
  const localRef = useRef(null)

  // Sincroniza la referencia externa y la interna
  useEffect(() => {
    if (!ref) return
    if (typeof ref === 'function') {
      ref(localRef.current)
    } else {
      ref.current = localRef.current
    }
  }, [ref])

  // Sincroniza el valor del input del DOM con el valor externo YYYY-MM-DD
  useEffect(() => {
    if (localRef.current) {
      const currentDomValue = localRef.current.value
      const parsedCurrent = parseMaskToDate(currentDomValue)
      if (parsedCurrent !== (value || '')) {
        localRef.current.value = formatDateToMask(value || '')
      }
    }
  }, [value])

  const handleInput = (e) => {
    const input = e.target
    const rawValue = input.value

    // Contar cuántos dígitos hay antes del cursor en el input sin formatear
    const selectionStart = input.selectionStart
    let digitsBefore = 0
    for (let i = 0; i < selectionStart; i++) {
      if (/\d/.test(rawValue[i])) {
        digitsBefore++
      }
    }

    const digits = cleanDigits(rawValue)
    const formatted = formatToDateMask(digits)

    // Actualiza el elemento DOM de forma síncrona para evitar saltos del cursor
    input.value = formatted

    const newCursorPos = getCursorPosition(formatted, digitsBefore)
    input.setSelectionRange(newCursorPos, newCursorPos)

    const isoDate = parseMaskToDate(formatted)

    if (onChange) {
      const eventMock = {
        ...e,
        target: {
          ...input,
          value: isoDate,
          name: props.name,
        },
      }
      onChange(eventMock)
    }
  }

  const handleKeyDown = (e) => {
    const input = e.target
    if (e.key === 'Backspace') {
      const { selectionStart, selectionEnd } = input
      if (selectionStart === selectionEnd && selectionStart > 0) {
        // Si el carácter que se va a borrar es una barra
        if (input.value[selectionStart - 1] === '/') {
          e.preventDefault()
          const val = input.value
          // Borrar la barra y también el dígito anterior a ella
          const newValue = val.slice(0, selectionStart - 2) + val.slice(selectionStart)
          const digits = cleanDigits(newValue)
          const formatted = formatToDateMask(digits)

          input.value = formatted

          const newCursorPos = Math.max(0, selectionStart - 2)
          input.setSelectionRange(newCursorPos, newCursorPos)

          const isoDate = parseMaskToDate(formatted)
          if (onChange) {
            const eventMock = {
              ...e,
              target: {
                ...input,
                value: isoDate,
                name: props.name,
              },
            }
            onChange(eventMock)
          }
        }
      }
    }
  }

  return (
    <div className="relative">
      <input
        ref={localRef}
        type="text"
        inputMode="numeric"
        pattern="[0-9]*"
        placeholder="DD/MM/YYYY"
        className={`input-base pr-12 ${error ? 'error' : ''} ${className}`}
        onChange={handleInput}
        onKeyDown={handleKeyDown}
        defaultValue={formatDateToMask(value || '')}
        {...props}
      />
      {/* Icono decorativo */}
      <span className="pointer-events-none absolute right-3.5 top-1/2 -translate-y-1/2 text-blue-brand opacity-60">
        <IconCalendar />
      </span>
    </div>
  )
})

export function FieldError({ message }) {
  if (!message) return null
  return (
    <p className="text-[12px] leading-[18px] font-medium" style={{ color: '#D32F2F' }}>
      {message}
    </p>
  )
}

export function SectionTitle({ children, className = '' }) {
  return (
    <p className={`text-[18px] leading-[24px] font-medium text-dark mb-1.5 ${className}`}>{children}</p>
  )
}

export function SectionSub({ children, className = '' }) {
  return (
    <p className={`text-[15px] leading-[22px] font-medium text-grey-500 mb-6 ${className}`}>{children}</p>
  )
}
